/**
 * Character Tracking Module
 * 캐릭터 추적 및 검증 시스템
 */

import { loadMemory, saveMemory, generateId, now } from './memory-manager';
import type { Character, EmotionPoint, SpeechLevel, WriterMemory } from './memory-manager';

// === Helper to find character ===
function findCharacter(memory: WriterMemory, nameOrAlias: string): Character | null {
  // Direct lookup
  if (memory.characters[nameOrAlias]) {
    return memory.characters[nameOrAlias];
  }
  // Alias lookup
  for (const char of Object.values(memory.characters)) {
    if (char.aliases?.includes(nameOrAlias)) {
      return char;
    }
  }
  return null;
}

// === Character CRUD ===

export function addCharacter(name: string, options?: {
  arc?: string;
  tone?: string;
  speechLevel?: SpeechLevel;
  attitude?: string;
  keywords?: string[];
  notes?: string;
}): Character | null {
  const memory = loadMemory();
  if (!memory) return null;

  if (memory.characters[name]) {
    return null; // Already exists
  }

  const character: Character = {
    id: generateId('char'),
    name,
    aliases: [],
    arc: options?.arc || '',
    tone: options?.tone || '',
    speechLevel: options?.speechLevel || '반말',
    attitude: options?.attitude || '',
    keywords: options?.keywords || [],
    timeline: [],
    notes: options?.notes || '',
    created: now(),
    updated: now()
  };

  memory.characters[name] = character;
  saveMemory(memory);
  return character;
}

export function updateCharacter(name: string, updates: Partial<Character>): Character | null {
  const memory = loadMemory();
  if (!memory) return null;

  const character = findCharacter(memory, name);
  if (!character) return null;

  // Apply updates (excluding id, name, created)
  const { id, name: _, created, ...allowedUpdates } = updates as any;
  Object.assign(character, allowedUpdates, { updated: now() });

  saveMemory(memory);
  return character;
}

export function removeCharacter(name: string): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  const character = findCharacter(memory, name);
  if (!character) return false;

  delete memory.characters[character.name];
  saveMemory(memory);
  return true;
}

export interface CharacterSummary {
  id: string;
  name: string;
  arc: string;
  tone: string;
  emotionCount: number;
  lastUpdated: string;
}

export function listCharacters(): CharacterSummary[] {
  const memory = loadMemory();
  if (!memory) return [];

  return Object.values(memory.characters).map(c => ({
    id: c.id,
    name: c.name,
    arc: c.arc,
    tone: c.tone,
    emotionCount: c.timeline?.length || 0,
    lastUpdated: c.updated
  }));
}

// === Alias Management ===

export function addAlias(characterName: string, alias: string): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  const character = findCharacter(memory, characterName);
  if (!character) return false;

  if (!character.aliases.includes(alias)) {
    character.aliases.push(alias);
    character.updated = now();
    saveMemory(memory);
  }
  return true;
}

export function removeAlias(characterName: string, alias: string): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  const character = findCharacter(memory, characterName);
  if (!character) return false;

  const idx = character.aliases.indexOf(alias);
  if (idx !== -1) {
    character.aliases.splice(idx, 1);
    character.updated = now();
    saveMemory(memory);
    return true;
  }
  return false;
}

export function resolveCharacter(nameOrAlias: string): Character | null {
  const memory = loadMemory();
  if (!memory) return null;
  return findCharacter(memory, nameOrAlias);
}

// === Emotion Timeline ===

export function addEmotionPoint(characterName: string, emotion: string, trigger: string, options?: {
  sceneId?: string;
  intensity?: 1 | 2 | 3 | 4 | 5;
}): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  const character = findCharacter(memory, characterName);
  if (!character) return false;

  const point: EmotionPoint = {
    timestamp: now(),
    sceneId: options?.sceneId,
    emotion,
    trigger,
    intensity: options?.intensity || 3
  };

  character.timeline.push(point);
  character.updated = now();
  saveMemory(memory);
  return true;
}

export function getEmotionTimeline(characterName: string): EmotionPoint[] {
  const character = resolveCharacter(characterName);
  return character?.timeline || [];
}

export function getLatestEmotion(characterName: string): EmotionPoint | null {
  const timeline = getEmotionTimeline(characterName);
  return timeline.length > 0 ? timeline[timeline.length - 1] : null;
}

export function getEmotionArc(characterName: string): string {
  const timeline = getEmotionTimeline(characterName);
  if (timeline.length === 0) return '';
  return timeline.map(e => e.emotion).join(' → ');
}

// === Dialogue Validation ===

export interface ValidationResult {
  status: 'PASS' | 'WARN' | 'FAIL';
  character: string;
  checks: {
    toneMatch: { passed: boolean; detail: string };
    speechLevelMatch: { passed: boolean; detail: string };
    keywordConsistency: { passed: boolean; detail: string };
  };
  suggestion: string;
}

export function detectSpeechLevel(text: string): SpeechLevel {
  // 존댓말 patterns
  const formal = /요$|습니다$|세요$|십시오$/;
  // 반말 patterns
  const informal = /야$|아$|어$|지$|는데$/;
  // 해체 patterns
  const casual = /임$|음$|ㅋ|ㅎ$/;

  const sentences = text.split(/[.!?]/).filter(s => s.trim());
  let formalCnt = 0, informalCnt = 0, casualCnt = 0;

  for (const s of sentences) {
    const t = s.trim();
    if (formal.test(t)) formalCnt++;
    if (informal.test(t)) informalCnt++;
    if (casual.test(t)) casualCnt++;
  }

  if (formalCnt > informalCnt && formalCnt > casualCnt) return '존댓말';
  if (casualCnt > informalCnt) return '해체';
  if (informalCnt > 0) return '반말';
  return '혼합';
}

export function validateDialogue(characterName: string, dialogue: string): ValidationResult {
  const character = resolveCharacter(characterName);

  if (!character) {
    return {
      status: 'FAIL',
      character: characterName,
      checks: {
        toneMatch: { passed: false, detail: '캐릭터를 찾을 수 없음' },
        speechLevelMatch: { passed: false, detail: '캐릭터를 찾을 수 없음' },
        keywordConsistency: { passed: false, detail: '캐릭터를 찾을 수 없음' }
      },
      suggestion: `"${characterName}" 캐릭터가 메모리에 없습니다.`
    };
  }

  // Check tone
  const exclamations = (dialogue.match(/!/g) || []).length;
  const toneCheck = { passed: true, detail: '톤 일치' };
  if (character.tone.includes('담백') && exclamations > 1) {
    toneCheck.passed = false;
    toneCheck.detail = `담백한 톤에 느낌표 ${exclamations}개는 과함`;
  }

  // Check speech level
  const detected = detectSpeechLevel(dialogue);
  const speechCheck = {
    passed: detected === character.speechLevel || detected === '혼합',
    detail: detected === character.speechLevel ? '말투 일치' : `기대: ${character.speechLevel}, 감지: ${detected}`
  };

  // Check keywords
  const keywordCheck = { passed: true, detail: '키워드 없음 (검사 생략)' };
  if (character.keywords.length > 0) {
    const hasKeyword = character.keywords.some(kw => dialogue.includes(kw));
    keywordCheck.passed = hasKeyword;
    keywordCheck.detail = hasKeyword ? '특징 키워드 포함' : `키워드 미포함: ${character.keywords.slice(0, 2).join(', ')}`;
  }

  const failCount = [toneCheck, speechCheck, keywordCheck].filter(c => !c.passed).length;
  const status: 'PASS' | 'WARN' | 'FAIL' = failCount === 0 ? 'PASS' : failCount >= 2 ? 'FAIL' : 'WARN';

  const suggestions: string[] = [];
  if (!toneCheck.passed) suggestions.push(`톤 조정 필요`);
  if (!speechCheck.passed) suggestions.push(`${character.speechLevel}로 말투 수정`);
  if (!keywordCheck.passed) suggestions.push(`특징 키워드 사용 고려`);

  return {
    status,
    character: character.name,
    checks: {
      toneMatch: toneCheck,
      speechLevelMatch: speechCheck,
      keywordConsistency: keywordCheck
    },
    suggestion: suggestions.length > 0 ? suggestions.join('. ') : '대사가 캐릭터와 잘 어울립니다.'
  };
}

// === Profile Generation ===

export function generateCharacterProfile(characterName: string): string {
  const character = resolveCharacter(characterName);

  if (!character) {
    return `# "${characterName}" 캐릭터를 찾을 수 없습니다`;
  }

  const latest = getLatestEmotion(characterName);
  const arc = getEmotionArc(characterName);

  let profile = `# ${character.name}\n\n`;

  if (character.aliases.length > 0) {
    profile += `**별칭**: ${character.aliases.join(', ')}\n\n`;
  }

  if (character.arc) {
    profile += `**캐릭터 아크**: ${character.arc}\n\n`;
  }

  if (character.tone) {
    profile += `**대사 톤**: ${character.tone}\n\n`;
  }

  profile += `**말투**: ${character.speechLevel}\n\n`;

  if (character.keywords.length > 0) {
    profile += `**핵심 키워드**: ${character.keywords.join(', ')}\n\n`;
  }

  if (latest) {
    profile += `**현재 감정**: ${latest.emotion} (강도: ${latest.intensity}/5)\n\n`;
  }

  if (character.attitude) {
    profile += `**태도**: ${character.attitude}\n\n`;
  }

  if (arc) {
    profile += `**감정 궤도**: ${arc}\n\n`;
  }

  if (character.notes) {
    profile += `**메모**: ${character.notes}\n\n`;
  }

  return profile.trim();
}

/**
 * memory-manager.ts
 *
 * Core memory management module for the Writer Memory System.
 * Handles all CRUD operations for .writer-memory/ storage.
 *
 * This is a REFERENCE IMPLEMENTATION that Claude reads when the skill
 * is activated. Written as real, runnable TypeScript with proper types,
 * error handling, and atomic operations.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync, statSync, renameSync, readdirSync } from "fs";
import { join, dirname } from "path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type SpeechLevel = "반말" | "존댓말" | "해체" | "혼합";

export type RelationshipType =
  | "romantic"
  | "familial"
  | "friendship"
  | "antagonistic"
  | "professional"
  | "mentor"
  | "complex";

export interface EmotionPoint {
  timestamp: string;
  sceneId?: string;
  /** Korean emotion word, e.g. "그리움" */
  emotion: string;
  /** What caused this emotion */
  trigger: string;
  intensity: 1 | 2 | 3 | 4 | 5;
}

export interface Character {
  id: string;
  name: string;
  aliases: string[];
  /** Arc summary, e.g. "체념->욕망자각->선택" */
  arc: string;
  /** Tone summary, e.g. "담백, 현재충실" */
  tone: string;
  speechLevel: SpeechLevel;
  /** Characteristic phrases/words */
  keywords: string[];
  /** Attitude summary (태도 요약) */
  attitude: string;
  timeline: EmotionPoint[];
  notes: string;
  created: string;
  updated: string;
  /** Words/patterns the character would NEVER say */
  taboo?: string[];
  /** Default emotional state */
  emotional_baseline?: string;
  /** What triggers emotional changes */
  triggers?: string[];
}

export interface WorldRule {
  id: string;
  category: string;
  description: string;
}

export interface Location {
  id: string;
  name: string;
  description: string;
  atmosphere: string;
  /** Other location IDs */
  connectedTo: string[];
}

export interface WorldMemory {
  name: string;
  era: string;
  atmosphere: string;
  rules: WorldRule[];
  locations: Location[];
  culturalNotes: string[];
  notes: string;
}

export interface RelationshipEvent {
  timestamp: string;
  sceneId?: string;
  change: string;
  catalyst: string;
}

export interface Relationship {
  id: string;
  /** Character ID */
  from: string;
  /** Character ID */
  to: string;
  type: RelationshipType;
  /** e.g. "일방적 짝사랑 -> 상호 이해" */
  dynamic: string;
  speechLevel?: SpeechLevel;
  evolution: RelationshipEvent[];
  notes?: string;
  created: string;
}

export interface Cut {
  order: number;
  type: "dialogue" | "narration" | "action" | "internal";
  content: string;
  character?: string;
  emotionTag?: string;
}

export interface Scene {
  id: string;
  title: string;
  chapter?: string;
  order: number;
  characters: string[];
  emotionTags: string[];
  cuts: Cut[];
  narrationTone?: string;
  notes?: string;
  created: string;
}

export interface Theme {
  id: string;
  name: string;
  description: string;
  keywords: string[];
  relatedCharacters: string[];
  relatedScenes: string[];
}

export interface SynopsisState {
  /** 주인공 태도 요약 */
  protagonistAttitude: string;
  /** 관계 핵심 구도 */
  coreRelationships: string;
  /** 정서적 테마 */
  emotionalTheme: string;
  /** 장르 vs 실제감정 대비 */
  genreVsRealEmotion: string;
  /** 엔딩 정서 잔상 */
  endingAftertaste: string;
  lastGenerated?: string;
}

export interface ProjectMeta {
  name: string;
  genre: string;
  /** ISO timestamp */
  created: string;
  /** ISO timestamp */
  updated: string;
}

export interface WriterMemory {
  version: "1.0";
  project: ProjectMeta;
  characters: Record<string, Character>;
  world: WorldMemory;
  relationships: Relationship[];
  scenes: Scene[];
  themes: Theme[];
  synopsis: SynopsisState;
}

export interface MemoryStats {
  characterCount: number;
  relationshipCount: number;
  sceneCount: number;
  themeCount: number;
  totalEmotionPoints: number;
  lastUpdated: string;
  storageSizeKB: number;
}

export interface SearchResult {
  type: "character" | "relationship" | "scene" | "theme" | "world";
  id: string;
  title: string;
  relevance: string;
  snippet: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MEMORY_DIR = ".writer-memory";
const MEMORY_FILE = "memory.json";
const BACKUP_DIR = "backups";
const MAX_BACKUPS = 20;

// ---------------------------------------------------------------------------
// Path Helpers
// ---------------------------------------------------------------------------

/** Returns the path to the main memory JSON file. */
export function getMemoryPath(): string {
  return join(MEMORY_DIR, MEMORY_FILE);
}

/** Returns the path to the backups directory. */
export function getBackupPath(): string {
  return join(MEMORY_DIR, BACKUP_DIR);
}

// ---------------------------------------------------------------------------
// ID Generation
// ---------------------------------------------------------------------------

/**
 * Generate a prefixed unique ID using unix timestamp + random suffix.
 * @param prefix - e.g. "char", "rel", "scene"
 * @returns e.g. "char_1706123456_a3f"
 */
export function generateId(prefix: string): string {
  const ts = Math.floor(Date.now() / 1000);
  const rand = Math.random().toString(36).slice(2, 5);
  return `${prefix}_${ts}_${rand}`;
}

// ---------------------------------------------------------------------------
// Timestamps
// ---------------------------------------------------------------------------

/** Returns the current time as an ISO 8601 string. */
export function now(): string {
  return new Date().toISOString();
}

/**
 * Format an ISO timestamp into Korean date format.
 * @param iso - ISO 8601 string
 * @returns e.g. "2024년 1월 24일"
 */
export function formatKoreanDate(iso: string): string {
  const d = new Date(iso);
  if (isNaN(d.getTime())) {
    return iso; // fallback for invalid dates
  }
  const year = d.getFullYear();
  const month = d.getMonth() + 1;
  const day = d.getDate();
  return `${year}년 ${month}월 ${day}일`;
}

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

/**
 * Create a fresh WriterMemory structure for a new project.
 * Also ensures the .writer-memory/ directory tree exists on disk.
 *
 * @param projectName - e.g. "이별의 온도"
 * @param genre - e.g. "멜로 / 성장 드라마"
 */
export function initMemory(projectName: string, genre: string): WriterMemory {
  const timestamp = now();

  // Ensure directory structure
  const memDir = MEMORY_DIR;
  const backDir = getBackupPath();
  if (!existsSync(memDir)) {
    mkdirSync(memDir, { recursive: true });
  }
  if (!existsSync(backDir)) {
    mkdirSync(backDir, { recursive: true });
  }

  const memory: WriterMemory = {
    version: "1.0",
    project: {
      name: projectName,
      genre,
      created: timestamp,
      updated: timestamp,
    },
    characters: {},
    world: {
      name: "",
      era: "",
      atmosphere: "",
      rules: [],
      locations: [],
      culturalNotes: [],
      notes: "",
    },
    relationships: [],
    scenes: [],
    themes: [],
    synopsis: {
      protagonistAttitude: "",
      coreRelationships: "",
      emotionalTheme: "",
      genreVsRealEmotion: "",
      endingAftertaste: "",
    },
  };

  saveMemory(memory);
  return memory;
}

// ---------------------------------------------------------------------------
// Core CRUD
// ---------------------------------------------------------------------------

/**
 * Load the writer memory from disk.
 * @returns The parsed WriterMemory, or null if the file does not exist or is corrupt.
 */
export function loadMemory(): WriterMemory | null {
  const memPath = getMemoryPath();
  try {
    if (!existsSync(memPath)) {
      return null;
    }
    const raw = readFileSync(memPath, "utf-8");
    const parsed = JSON.parse(raw) as WriterMemory;
    return parsed;
  } catch (err) {
    console.error(`[writer-memory] Failed to load memory from ${memPath}:`, err);
    return null;
  }
}

/**
 * Persist memory to disk using an atomic write (write to temp, then rename).
 * Automatically updates the project.updated timestamp and creates a backup
 * of the previous state.
 *
 * @returns true on success, false on failure
 */
export function saveMemory(memory: WriterMemory): boolean {
  const memPath = getMemoryPath();
  const memDir = dirname(memPath);

  try {
    // Ensure directory exists
    if (!existsSync(memDir)) {
      mkdirSync(memDir, { recursive: true });
    }

    // Backup existing file before overwriting
    if (existsSync(memPath)) {
      try {
        const existing = readFileSync(memPath, "utf-8");
        const existingMemory = JSON.parse(existing) as WriterMemory;
        createBackup(existingMemory);
      } catch {
        // If backup fails, continue with save anyway
      }
    }

    // Update timestamp
    memory.project.updated = now();

    // Atomic write: write to temp file, then rename
    const tmpPath = memPath + ".tmp";
    const json = JSON.stringify(memory, null, 2);
    writeFileSync(tmpPath, json, "utf-8");
    renameSync(tmpPath, memPath);

    return true;
  } catch (err) {
    console.error(`[writer-memory] Failed to save memory to ${memPath}:`, err);
    return false;
  }
}

/**
 * Create a timestamped backup of the given memory state.
 * Old backups beyond MAX_BACKUPS are pruned automatically.
 *
 * @returns The backup file path, or empty string on failure.
 */
export function createBackup(memory: WriterMemory): string {
  const backDir = getBackupPath();

  try {
    if (!existsSync(backDir)) {
      mkdirSync(backDir, { recursive: true });
    }

    const ts = new Date().toISOString().replace(/[:.]/g, "-");
    const backupFile = join(backDir, `memory-${ts}.json`);
    const json = JSON.stringify(memory, null, 2);
    writeFileSync(backupFile, json, "utf-8");

    // Prune old backups
    pruneBackups(backDir);

    return backupFile;
  } catch (err) {
    console.error("[writer-memory] Failed to create backup:", err);
    return "";
  }
}

/**
 * Remove oldest backup files when count exceeds MAX_BACKUPS.
 */
function pruneBackups(backDir: string): void {
  try {
    const files = readdirSync(backDir)
      .filter((f) => f.startsWith("memory-") && f.endsWith(".json"))
      .sort(); // lexicographic sort works because filenames contain ISO timestamps

    while (files.length > MAX_BACKUPS) {
      const oldest = files.shift()!;
      const fullPath = join(backDir, oldest);
      // Use writeFileSync trick: overwrite then unlink is not needed;
      // simply use fs.unlinkSync
      require("fs").unlinkSync(fullPath);
    }
  } catch {
    // Non-critical; ignore pruning errors
  }
}

// ---------------------------------------------------------------------------
// Memory Stats
// ---------------------------------------------------------------------------

/**
 * Compute aggregate statistics about the memory store.
 */
export function getMemoryStats(memory: WriterMemory): MemoryStats {
  const characters = Object.values(memory.characters);
  const totalEmotionPoints = characters.reduce(
    (sum, c) => sum + c.timeline.length,
    0
  );

  let storageSizeKB = 0;
  try {
    const memPath = getMemoryPath();
    if (existsSync(memPath)) {
      const stat = statSync(memPath);
      storageSizeKB = Math.round((stat.size / 1024) * 100) / 100;
    }
  } catch {
    // If stat fails, leave at 0
  }

  return {
    characterCount: characters.length,
    relationshipCount: memory.relationships.length,
    sceneCount: memory.scenes.length,
    themeCount: memory.themes.length,
    totalEmotionPoints,
    lastUpdated: memory.project.updated,
    storageSizeKB,
  };
}

// ---------------------------------------------------------------------------
// Search / Query Helpers
// ---------------------------------------------------------------------------

/**
 * Find a character by exact name match (case-sensitive).
 * @param name - e.g. "서연"
 */
export function findCharacterByName(
  memory: WriterMemory,
  name: string
): Character | null {
  for (const char of Object.values(memory.characters)) {
    if (char.name === name) {
      return char;
    }
  }
  return null;
}

/**
 * Find a character by one of their aliases.
 * @param alias - e.g. "연이" (nickname for 서연)
 */
export function findCharacterByAlias(
  memory: WriterMemory,
  alias: string
): Character | null {
  for (const char of Object.values(memory.characters)) {
    if (char.aliases.includes(alias)) {
      return char;
    }
  }
  return null;
}

/**
 * Find a relationship between two characters (in either direction).
 * @param char1 - Character ID
 * @param char2 - Character ID
 */
export function findRelationship(
  memory: WriterMemory,
  char1: string,
  char2: string
): Relationship | null {
  return (
    memory.relationships.find(
      (r) =>
        (r.from === char1 && r.to === char2) ||
        (r.from === char2 && r.to === char1)
    ) ?? null
  );
}

/**
 * Find a scene by its unique ID.
 */
export function findSceneById(
  memory: WriterMemory,
  id: string
): Scene | null {
  return memory.scenes.find((s) => s.id === id) ?? null;
}

/**
 * Find all scenes that include a given character.
 * @param characterId - Character ID to search for
 */
export function findScenesByCharacter(
  memory: WriterMemory,
  characterId: string
): Scene[] {
  return memory.scenes.filter((s) => s.characters.includes(characterId));
}

/**
 * Full-text search across all memory domains.
 * Matches query substring (case-insensitive) against names, descriptions,
 * notes, keywords, and content fields.
 *
 * @param query - Search string, e.g. "그리움" or "카페"
 * @returns Matching results sorted by domain priority
 */
export function searchMemory(
  memory: WriterMemory,
  query: string
): SearchResult[] {
  const results: SearchResult[] = [];
  const q = query.toLowerCase();

  const matches = (text: string | undefined): boolean =>
    text != null && text.toLowerCase().includes(q);

  // Search characters
  for (const char of Object.values(memory.characters)) {
    if (
      matches(char.name) ||
      matches(char.arc) ||
      matches(char.tone) ||
      matches(char.attitude) ||
      matches(char.notes) ||
      char.aliases.some(matches) ||
      char.keywords.some(matches)
    ) {
      results.push({
        type: "character",
        id: char.id,
        title: char.name,
        relevance: matches(char.name) ? "name" : "content",
        snippet: truncate(
          [char.arc, char.tone, char.attitude].filter(Boolean).join(" | "),
          120
        ),
      });
    }
  }

  // Search relationships
  for (const rel of memory.relationships) {
    if (matches(rel.dynamic) || matches(rel.notes)) {
      const fromChar = memory.characters[rel.from];
      const toChar = memory.characters[rel.to];
      const fromName = fromChar?.name ?? rel.from;
      const toName = toChar?.name ?? rel.to;
      results.push({
        type: "relationship",
        id: rel.id,
        title: `${fromName} <-> ${toName}`,
        relevance: "content",
        snippet: truncate(rel.dynamic, 120),
      });
    }
  }

  // Search scenes
  for (const scene of memory.scenes) {
    if (
      matches(scene.title) ||
      matches(scene.narrationTone) ||
      matches(scene.notes) ||
      scene.emotionTags.some(matches) ||
      scene.cuts.some((c) => matches(c.content))
    ) {
      results.push({
        type: "scene",
        id: scene.id,
        title: scene.title,
        relevance: matches(scene.title) ? "title" : "content",
        snippet: truncate(
          scene.cuts
            .slice(0, 2)
            .map((c) => c.content)
            .join(" / "),
          120
        ),
      });
    }
  }

  // Search themes
  for (const theme of memory.themes) {
    if (
      matches(theme.name) ||
      matches(theme.description) ||
      theme.keywords.some(matches)
    ) {
      results.push({
        type: "theme",
        id: theme.id,
        title: theme.name,
        relevance: matches(theme.name) ? "name" : "content",
        snippet: truncate(theme.description, 120),
      });
    }
  }

  // Search world
  const world = memory.world;
  if (
    matches(world.name) ||
    matches(world.era) ||
    matches(world.atmosphere) ||
    matches(world.notes) ||
    world.culturalNotes.some(matches) ||
    world.locations.some(
      (l) => matches(l.name) || matches(l.description) || matches(l.atmosphere)
    )
  ) {
    // Find the most relevant location if applicable
    const matchedLoc = world.locations.find(
      (l) => matches(l.name) || matches(l.description)
    );
    results.push({
      type: "world",
      id: matchedLoc?.id ?? "world",
      title: matchedLoc?.name ?? (world.name || "World"),
      relevance: "content",
      snippet: truncate(
        matchedLoc?.description ?? world.atmosphere ?? world.notes,
        120
      ),
    });
  }

  return results;
}

/** Truncate a string to maxLen, appending ellipsis if needed. */
function truncate(text: string | undefined, maxLen: number): string {
  if (!text) return "";
  if (text.length <= maxLen) return text;
  return text.slice(0, maxLen - 1) + "\u2026";
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

/**
 * Validate the structural integrity of a WriterMemory object.
 * Checks for required fields, dangling references, and data consistency.
 */
export function validateMemory(memory: WriterMemory): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Version check
  if (memory.version !== "1.0") {
    errors.push(`Unsupported version: "${memory.version}" (expected "1.0")`);
  }

  // Project meta
  if (!memory.project.name) {
    errors.push("Project name is empty");
  }
  if (!memory.project.genre) {
    warnings.push("Project genre is empty");
  }
  if (!memory.project.created) {
    errors.push("Project created timestamp is missing");
  }

  // Characters
  const charIds = new Set(Object.keys(memory.characters));
  for (const [id, char] of Object.entries(memory.characters)) {
    if (char.id !== id) {
      errors.push(
        `Character key "${id}" does not match character.id "${char.id}"`
      );
    }
    if (!char.name) {
      errors.push(`Character "${id}" has no name`);
    }
    for (const ep of char.timeline) {
      if (ep.intensity < 1 || ep.intensity > 5) {
        warnings.push(
          `Character "${char.name}" has emotion point with intensity ${ep.intensity} (expected 1-5)`
        );
      }
      if (ep.sceneId && !memory.scenes.some((s) => s.id === ep.sceneId)) {
        warnings.push(
          `Character "${char.name}" references non-existent scene "${ep.sceneId}" in timeline`
        );
      }
    }
  }

  // Relationships
  for (const rel of memory.relationships) {
    if (!charIds.has(rel.from)) {
      errors.push(
        `Relationship "${rel.id}" references non-existent character "${rel.from}"`
      );
    }
    if (!charIds.has(rel.to)) {
      errors.push(
        `Relationship "${rel.id}" references non-existent character "${rel.to}"`
      );
    }
    if (rel.from === rel.to) {
      warnings.push(
        `Relationship "${rel.id}" is self-referential (from === to === "${rel.from}")`
      );
    }
  }

  // Scenes
  const sceneIds = new Set<string>();
  for (const scene of memory.scenes) {
    if (sceneIds.has(scene.id)) {
      errors.push(`Duplicate scene ID: "${scene.id}"`);
    }
    sceneIds.add(scene.id);

    for (const charId of scene.characters) {
      if (!charIds.has(charId)) {
        warnings.push(
          `Scene "${scene.title}" references non-existent character "${charId}"`
        );
      }
    }
    if (scene.cuts.length === 0) {
      warnings.push(`Scene "${scene.title}" has no cuts`);
    }
  }

  // Themes
  for (const theme of memory.themes) {
    for (const charId of theme.relatedCharacters) {
      if (!charIds.has(charId)) {
        warnings.push(
          `Theme "${theme.name}" references non-existent character "${charId}"`
        );
      }
    }
    for (const sid of theme.relatedScenes) {
      if (!sceneIds.has(sid)) {
        warnings.push(
          `Theme "${theme.name}" references non-existent scene "${sid}"`
        );
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
  };
}

/**
 * Relationship Graph Module for Writer Memory System
 *
 * Tracks character relationships with evolution over time,
 * Korean relationship types, and graph-based analysis.
 */

import { loadMemory, saveMemory, generateId, now } from './memory-manager';
import type {
  Relationship,
  RelationshipType,
  RelationshipEvent,
  SpeechLevel,
  WriterMemory
} from './memory-manager';

// ============================================================================
// Relationship CRUD Operations
// ============================================================================

/**
 * Create a new relationship between two characters
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @param type - Relationship type
 * @param options - Optional relationship properties
 * @returns Created relationship
 */
export function addRelationship(
  char1Name: string,
  char2Name: string,
  type: RelationshipType,
  options?: {
    dynamic?: Relationship['dynamic'];
    speechLevel?: SpeechLevel;
    notes?: string;
  }
): Relationship | null {
  const memory = loadMemory();
  if (!memory) return null;

  // Check if relationship already exists
  const existing = memory.relationships.find(r =>
    (r.from === char1Name && r.to === char2Name) ||
    (r.from === char2Name && r.to === char1Name)
  );

  if (existing) {
    return null;
  }

  const relationship: Relationship = {
    id: generateId('rel'),
    from: char1Name,
    to: char2Name,
    type,
    dynamic: options?.dynamic || 'stable',
    speechLevel: options?.speechLevel,
    notes: options?.notes,
    evolution: [],
    created: now()
  };

  memory.relationships.push(relationship);
  saveMemory(memory);

  return relationship;
}

/**
 * Update an existing relationship with partial data
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @param updates - Partial relationship updates
 * @returns Updated relationship
 */
export function updateRelationship(
  char1Name: string,
  char2Name: string,
  updates: Partial<Omit<Relationship, 'id' | 'from' | 'to' | 'created'>>
): Relationship | null {
  const memory = loadMemory();
  if (!memory) return null;

  const relationship = getRelationship(char1Name, char2Name);

  if (!relationship) {
    return null;
  }

  Object.assign(relationship, updates);
  saveMemory(memory);

  return relationship;
}

/**
 * Remove a relationship between two characters
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 */
export function removeRelationship(char1Name: string, char2Name: string): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  const index = memory.relationships.findIndex(r =>
    (r.from === char1Name && r.to === char2Name) ||
    (r.from === char2Name && r.to === char1Name)
  );

  if (index === -1) {
    return false;
  }

  memory.relationships.splice(index, 1);
  saveMemory(memory);
  return true;
}

/**
 * Get relationship between two characters (direction-agnostic)
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @returns Relationship or undefined
 */
export function getRelationship(char1Name: string, char2Name: string): Relationship | undefined {
  const memory = loadMemory();
  if (!memory) return undefined;

  return memory.relationships.find(r =>
    (r.from === char1Name && r.to === char2Name) ||
    (r.from === char2Name && r.to === char1Name)
  );
}

/**
 * List all relationships, optionally filtered by character
 *
 * @param characterName - Optional character to filter by
 * @returns Array of relationships
 */
export function listRelationships(characterName?: string): Relationship[] {
  const memory = loadMemory();
  if (!memory) return [];

  if (!characterName) {
    return memory.relationships;
  }

  return memory.relationships.filter(r =>
    r.from === characterName || r.to === characterName
  );
}

// ============================================================================
// Relationship Evolution
// ============================================================================

/**
 * Add a timeline event to a relationship
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @param change - Description of relationship change
 * @param catalyst - What caused the change
 * @param sceneId - Optional scene reference
 * @returns Created event
 */
export function addRelationshipEvent(
  char1Name: string,
  char2Name: string,
  change: string,
  catalyst: string,
  sceneId?: string
): RelationshipEvent | null {
  const relationship = getRelationship(char1Name, char2Name);

  if (!relationship) {
    return null;
  }

  const event: RelationshipEvent = {
    timestamp: now(),
    change,
    catalyst,
    sceneId
  };

  relationship.evolution.push(event);

  const memory = loadMemory();
  if (!memory) return null;

  saveMemory(memory);

  return event;
}

/**
 * Get all timeline events for a relationship
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @returns Array of events sorted by timestamp
 */
export function getRelationshipTimeline(char1Name: string, char2Name: string): RelationshipEvent[] {
  const relationship = getRelationship(char1Name, char2Name);

  if (!relationship) {
    return [];
  }

  return relationship.evolution.sort((a, b) => a.timestamp.localeCompare(b.timestamp));
}

/**
 * Get relationship arc summary (e.g., "첫만남 → 오해 → 화해")
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @returns Arc summary string
 */
export function getRelationshipArc(char1Name: string, char2Name: string): string {
  const timeline = getRelationshipTimeline(char1Name, char2Name);

  if (timeline.length === 0) {
    return '변화 없음';
  }

  return timeline.map(e => e.change).join(' → ');
}

// ============================================================================
// Graph Operations
// ============================================================================

/**
 * Get all connections for a character with direction info
 *
 * @param characterName - Character name
 * @returns Connections with direction (outgoing/incoming/mutual)
 */
export function getCharacterConnections(characterName: string): Array<{
  relationship: Relationship;
  direction: 'outgoing' | 'incoming' | 'mutual';
  otherCharacter: string;
}> {
  const relationships = listRelationships(characterName);

  return relationships.map(r => {
    const isFrom = r.from === characterName;
    return {
      relationship: r,
      direction: 'mutual' as const, // Most relationships are bidirectional
      otherCharacter: isFrom ? r.to : r.from
    };
  });
}

/**
 * Get full relationship graph
 *
 * @returns Graph with nodes (characters) and edges (relationships)
 */
export function getRelationshipWeb(): {
  nodes: string[];
  edges: Array<{ from: string; to: string; type: RelationshipType }>
} {
  const memory = loadMemory();
  if (!memory) return { nodes: [], edges: [] };

  const nodes = new Set<string>();
  const edges: Array<{ from: string; to: string; type: RelationshipType }> = [];

  memory.relationships.forEach(r => {
    nodes.add(r.from);
    nodes.add(r.to);
    edges.push({ from: r.from, to: r.to, type: r.type });
  });

  return {
    nodes: Array.from(nodes),
    edges
  };
}

// ============================================================================
// Korean Labels
// ============================================================================

/**
 * Get Korean label for relationship type
 *
 * @param type - Relationship type
 * @returns Korean label
 */
export function getKoreanRelationType(type: RelationshipType): string {
  const labels: Record<RelationshipType, string> = {
    romantic: '연인',
    familial: '가족',
    friendship: '우정',
    antagonistic: '적대',
    professional: '직업적',
    mentor: '사제',
    complex: '복합적'
  };

  return labels[type];
}

// ============================================================================
// Profile Generation
// ============================================================================

/**
 * Generate markdown profile for a relationship
 *
 * @param char1Name - First character name
 * @param char2Name - Second character name
 * @returns Markdown profile
 */
export function generateRelationshipProfile(char1Name: string, char2Name: string): string {
  const relationship = getRelationship(char1Name, char2Name);

  if (!relationship) {
    return `# ${char1Name} ↔ ${char2Name}\n\n관계 정보 없음`;
  }

  const timeline = getRelationshipTimeline(char1Name, char2Name);
  const arc = getRelationshipArc(char1Name, char2Name);

  let profile = `# ${char1Name} ↔ ${char2Name}\n\n`;
  profile += `**관계 유형**: ${getKoreanRelationType(relationship.type)}\n`;
  profile += `**상태**: ${relationship.dynamic}\n`;

  if (relationship.speechLevel) {
    profile += `**말투**: ${relationship.speechLevel}\n`;
  }

  if (relationship.notes) {
    profile += `\n## 설명\n${relationship.notes}\n`;
  }

  if (timeline.length > 0) {
    profile += `\n## 관계 흐름\n${arc}\n\n`;
    profile += `## 주요 사건\n`;
    timeline.forEach(e => {
      profile += `- **${e.change}**: ${e.catalyst}`;
      if (e.sceneId) {
        profile += ` (${e.sceneId})`;
      }
      profile += '\n';
    });
  }

  return profile;
}

/**
 * Generate ASCII map of all relationships with symbols
 *
 * @returns ASCII relationship map
 */
export function generateRelationshipMap(): string {
  const web = getRelationshipWeb();

  if (web.nodes.length === 0) {
    return '관계 없음';
  }

  const symbols: Record<RelationshipType, string> = {
    romantic: '♥',
    familial: '家',
    friendship: '友',
    antagonistic: '敵',
    professional: '職',
    mentor: '師',
    complex: '複'
  };

  let map = '# 관계 지도\n\n';

  web.nodes.forEach(node => {
    const connections = getCharacterConnections(node);
    if (connections.length > 0) {
      map += `${node}:\n`;
      connections.forEach(conn => {
        const symbol = symbols[conn.relationship.type];
        map += `  ${symbol} ${conn.otherCharacter} (${getKoreanRelationType(conn.relationship.type)})\n`;
      });
      map += '\n';
    }
  });

  return map;
}

import { loadMemory, saveMemory, findSceneById, findScenesByCharacter, generateId, now } from './memory-manager';
import type { Scene, Cut, WriterMemory } from './memory-manager';

// === Korean Emotion Vocabulary ===
const EMOTION_VOCABULARY: string[] = [
  "긴장", "설렘", "불안", "평온", "갈등",
  "슬픔", "기쁨", "분노", "체념", "희망",
  "외로움", "그리움", "애틋함", "당혹", "환희",
  "공포", "안도", "후회", "결의", "허탈"
];

const CUT_TYPE_LABELS: Record<string, string> = {
  dialogue: "대사",
  narration: "내레이션",
  action: "액션",
  internal: "내면"
};

// === Type Definitions ===
export interface SceneSummary {
  id: string;
  title: string;
  chapter?: string;
  order: number;
  characterCount: number;
  cutCount: number;
  emotionTags: string[];
}

export interface SceneFlowEntry {
  order: number;
  title: string;
  chapter?: string;
  primaryEmotion: string;
  characters: string[];
  cutCount: number;
}

// === Scene CRUD ===

export function addScene(title: string, options?: {
  chapter?: string;
  characters?: string[];
  emotionTags?: string[];
  narrationTone?: string;
  notes?: string;
}): Scene | null {
  try {
    const memory = loadMemory();

    const newScene: Scene = {
      id: generateId('scene'),
      title,
      chapter: options?.chapter,
      characters: options?.characters || [],
      emotionTags: options?.emotionTags || [],
      cuts: [],
      narrationTone: options?.narrationTone || '',
      notes: options?.notes || '',
      order: memory.scenes.length,
      created: now()
    };

    memory.scenes.push(newScene);
    saveMemory(memory);

    return newScene;
  } catch (error) {
    console.error('Failed to add scene:', error);
    return null;
  }
}

export function updateScene(sceneId: string, updates: Partial<Scene>): Scene | null {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return null;
    }

    // Apply updates (preserve immutable fields)
    Object.assign(scene, {
      ...updates,
      id: scene.id,
      created: scene.created
    });

    saveMemory(memory);
    return scene;
  } catch (error) {
    console.error('Failed to update scene:', error);
    return null;
  }
}

export function removeScene(sceneId: string): boolean {
  try {
    const memory = loadMemory();
    const index = memory.scenes.findIndex(s => s.id === sceneId);

    if (index === -1) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    memory.scenes.splice(index, 1);

    // Reorder remaining scenes
    memory.scenes.forEach((scene, idx) => {
      scene.order = idx;
    });

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to remove scene:', error);
    return false;
  }
}

export function getScene(sceneId: string): Scene | null {
  try {
    const memory = loadMemory();
    return findSceneById(memory, sceneId);
  } catch (error) {
    console.error('Failed to get scene:', error);
    return null;
  }
}

export function listScenes(options?: {
  chapter?: string;
  character?: string;
  emotionTag?: string;
}): SceneSummary[] {
  try {
    const memory = loadMemory();
    let scenes = [...memory.scenes];

    // Apply filters
    if (options?.chapter) {
      scenes = scenes.filter(s => s.chapter === options.chapter);
    }

    if (options?.character) {
      scenes = scenes.filter(s => s.characters.includes(options.character!));
    }

    if (options?.emotionTag) {
      scenes = scenes.filter(s => s.emotionTags.includes(options.emotionTag!));
    }

    // Sort by order
    scenes.sort((a, b) => a.order - b.order);

    // Convert to summaries
    return scenes.map(scene => ({
      id: scene.id,
      title: scene.title,
      chapter: scene.chapter,
      order: scene.order,
      characterCount: scene.characters.length,
      cutCount: scene.cuts.length,
      emotionTags: scene.emotionTags
    }));
  } catch (error) {
    console.error('Failed to list scenes:', error);
    return [];
  }
}

// === Cut Management (콘티 컷) ===

export function addCut(sceneId: string, cut: {
  type: "dialogue" | "narration" | "action" | "internal";
  content: string;
  character?: string;
  emotionTag?: string;
}): boolean {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    const newCut: Cut = {
      order: scene.cuts.length,
      type: cut.type,
      content: cut.content,
      character: cut.character,
      emotionTag: cut.emotionTag
    };

    scene.cuts.push(newCut);

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to add cut:', error);
    return false;
  }
}

export function updateCut(sceneId: string, cutOrder: number, updates: Partial<Cut>): boolean {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    const cut = scene.cuts.find(c => c.order === cutOrder);

    if (!cut) {
      console.error(`Cut not found: order ${cutOrder} in scene ${sceneId}`);
      return false;
    }

    // Apply updates (preserve order)
    Object.assign(cut, {
      ...updates,
      order: cut.order
    });

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to update cut:', error);
    return false;
  }
}

export function removeCut(sceneId: string, cutOrder: number): boolean {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    const index = scene.cuts.findIndex(c => c.order === cutOrder);

    if (index === -1) {
      console.error(`Cut not found: order ${cutOrder} in scene ${sceneId}`);
      return false;
    }

    scene.cuts.splice(index, 1);

    // Reorder remaining cuts
    scene.cuts.forEach((cut, idx) => {
      cut.order = idx;
    });

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to remove cut:', error);
    return false;
  }
}

export function reorderCuts(sceneId: string, newOrder: number[]): boolean {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    if (newOrder.length !== scene.cuts.length) {
      console.error('New order length does not match cuts length');
      return false;
    }

    // Validate all indices are present
    const sortedOrder = [...newOrder].sort((a, b) => a - b);
    for (let i = 0; i < sortedOrder.length; i++) {
      if (sortedOrder[i] !== i) {
        console.error('Invalid order array: must contain all indices 0 to n-1');
        return false;
      }
    }

    // Reorder cuts
    const reorderedCuts: Cut[] = newOrder.map(oldIdx => scene.cuts[oldIdx]);
    reorderedCuts.forEach((cut, newIdx) => {
      cut.order = newIdx;
    });

    scene.cuts = reorderedCuts;

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to reorder cuts:', error);
    return false;
  }
}

// === Emotion Tags ===

export function addEmotionTag(sceneId: string, tag: string): boolean {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    if (scene.emotionTags.includes(tag)) {
      console.warn(`Emotion tag already exists: ${tag}`);
      return true; // Not an error
    }

    scene.emotionTags.push(tag);

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to add emotion tag:', error);
    return false;
  }
}

export function removeEmotionTag(sceneId: string, tag: string): boolean {
  try {
    const memory = loadMemory();
    const scene = findSceneById(memory, sceneId);

    if (!scene) {
      console.error(`Scene not found: ${sceneId}`);
      return false;
    }

    const index = scene.emotionTags.indexOf(tag);

    if (index === -1) {
      console.warn(`Emotion tag not found: ${tag}`);
      return true; // Not an error
    }

    scene.emotionTags.splice(index, 1);

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to remove emotion tag:', error);
    return false;
  }
}

export function getScenesByEmotion(emotionTag: string): Scene[] {
  try {
    const memory = loadMemory();
    return memory.scenes
      .filter(scene => scene.emotionTags.includes(emotionTag))
      .sort((a, b) => a.order - b.order);
  } catch (error) {
    console.error('Failed to get scenes by emotion:', error);
    return [];
  }
}

export function getAllEmotionTags(): { tag: string; count: number }[] {
  try {
    const memory = loadMemory();
    const tagCounts = new Map<string, number>();

    memory.scenes.forEach(scene => {
      scene.emotionTags.forEach(tag => {
        tagCounts.set(tag, (tagCounts.get(tag) || 0) + 1);
      });
    });

    return Array.from(tagCounts.entries())
      .map(([tag, count]) => ({ tag, count }))
      .sort((a, b) => b.count - a.count);
  } catch (error) {
    console.error('Failed to get all emotion tags:', error);
    return [];
  }
}

// === Scene Organization ===

export function reorderScenes(sceneIds: string[]): boolean {
  try {
    const memory = loadMemory();

    if (sceneIds.length !== memory.scenes.length) {
      console.error('Scene IDs length does not match scenes length');
      return false;
    }

    // Validate all IDs exist
    const sceneMap = new Map(memory.scenes.map(s => [s.id, s]));
    for (const id of sceneIds) {
      if (!sceneMap.has(id)) {
        console.error(`Scene not found: ${id}`);
        return false;
      }
    }

    // Reorder scenes
    memory.scenes = sceneIds.map(id => sceneMap.get(id)!);
    memory.scenes.forEach((scene, idx) => {
      scene.order = idx;
    });

    saveMemory(memory);
    return true;
  } catch (error) {
    console.error('Failed to reorder scenes:', error);
    return false;
  }
}

export function getSceneFlow(): SceneFlowEntry[] {
  try {
    const memory = loadMemory();

    return memory.scenes
      .sort((a, b) => a.order - b.order)
      .map(scene => ({
        order: scene.order + 1, // 1-indexed for display
        title: scene.title,
        chapter: scene.chapter,
        primaryEmotion: scene.emotionTags[0] || "감정 미설정",
        characters: scene.characters,
        cutCount: scene.cuts.length
      }));
  } catch (error) {
    console.error('Failed to get scene flow:', error);
    return [];
  }
}

// === Scene Profile Generation ===

export function generateSceneProfile(sceneId: string): string {
  try {
    const scene = getScene(sceneId);

    if (!scene) {
      return `# 오류: 장면을 찾을 수 없습니다 (${sceneId})`;
    }

    let profile = `# 장면: ${scene.title}\n\n`;

    if (scene.chapter) {
      profile += `**챕터**: ${scene.chapter}\n`;
    }

    if (scene.characters.length > 0) {
      profile += `**등장인물**: ${scene.characters.join(', ')}\n`;
    }

    if (scene.emotionTags.length > 0) {
      profile += `**감정 태그**: ${scene.emotionTags.join(', ')}\n`;
    }

    if (scene.narrationTone) {
      profile += `**내레이션 톤**: ${scene.narrationTone}\n`;
    }

    if (scene.notes) {
      profile += `\n**노트**: ${scene.notes}\n`;
    }

    profile += `\n## 컷 구성\n\n`;

    if (scene.cuts.length === 0) {
      profile += `*(컷이 아직 추가되지 않았습니다)*\n`;
    } else {
      scene.cuts.forEach(cut => {
        const typeLabel = CUT_TYPE_LABELS[cut.type] || cut.type;
        const charPart = cut.character ? `/${cut.character}` : '';
        const emotionPart = cut.emotionTag ? ` (감정: ${cut.emotionTag})` : '';

        profile += `${cut.order + 1}. [${typeLabel}${charPart}] ${cut.content}${emotionPart}\n`;
      });
    }

    return profile;
  } catch (error) {
    console.error('Failed to generate scene profile:', error);
    return `# 오류: 장면 프로필 생성 실패`;
  }
}

export function generateSceneList(): string {
  try {
    const memory = loadMemory();

    let list = `## 전체 장면 목록\n\n`;
    list += `| # | 제목 | 챕터 | 감정 | 등장인물 | 컷 수 |\n`;
    list += `|---|------|------|------|---------|-------|\n`;

    if (memory.scenes.length === 0) {
      list += `| - | *(장면이 아직 추가되지 않았습니다)* | - | - | - | - |\n`;
      return list;
    }

    const sortedScenes = [...memory.scenes].sort((a, b) => a.order - b.order);

    sortedScenes.forEach(scene => {
      const sceneNum = scene.order + 1;
      const title = scene.title;
      const chapter = scene.chapter || '-';
      const emotions = scene.emotionTags.length > 0
        ? scene.emotionTags.join(', ')
        : '-';
      const characters = scene.characters.length > 0
        ? scene.characters.join(', ')
        : '-';
      const cutCount = scene.cuts.length;

      list += `| ${sceneNum} | ${title} | ${chapter} | ${emotions} | ${characters} | ${cutCount} |\n`;
    });

    return list;
  } catch (error) {
    console.error('Failed to generate scene list:', error);
    return `## 오류: 장면 목록 생성 실패`;
  }
}

// Export emotion vocabulary for external use
export { EMOTION_VOCABULARY, CUT_TYPE_LABELS };

/**
 * Synopsis Builder - 정서 중심 시놉시스 생성기
 *
 * Korean writers think: emotion → relationship → event → plot
 * NOT plot-first!
 */

import { loadMemory, saveMemory, now } from './memory-manager';
import type { WriterMemory, Character, Relationship, Scene, SynopsisState } from './memory-manager';

// === Synopsis Generation ===

export function generateSynopsis(options?: {
  protagonist?: string;
  format?: 'full' | 'brief' | 'pitch';
}): string | null {
  const memory = loadMemory();
  if (!memory) return null;

  const format = options?.format || 'full';
  const protagonist = options?.protagonist;

  const attitude = extractProtagonistAttitude(memory, protagonist);
  const relationships = extractCoreRelationships(memory, protagonist);
  const theme = extractEmotionalTheme(memory);
  const genreContrast = extractGenreVsEmotion(memory);
  const aftertaste = extractEndingAftertaste(memory);

  switch (format) {
    case 'brief':
      return formatBriefSynopsis(attitude, relationships, theme, memory);
    case 'pitch':
      return formatPitchSynopsis(attitude, relationships, theme, genreContrast, memory);
    default:
      return formatFullSynopsis(attitude, relationships, theme, genreContrast, aftertaste, memory);
  }
}

// === 5 Essential Element Extractors ===

function findProtagonist(memory: WriterMemory, name?: string): Character | null {
  const chars = Object.values(memory.characters);
  if (name) {
    return chars.find(c => c.name === name || c.aliases?.includes(name)) || null;
  }
  return chars[0] || null;
}

export function extractProtagonistAttitude(memory: WriterMemory, protagonistName?: string): string {
  const protagonist = findProtagonist(memory, protagonistName);

  if (!protagonist) {
    return '⚠️ 주인공 정보 없음. 캐릭터를 먼저 등록하세요.';
  }

  const parts: string[] = [];
  if (protagonist.arc) parts.push(protagonist.arc);
  if (protagonist.attitude) parts.push(protagonist.attitude);

  if (parts.length === 0) {
    return `⚠️ ${protagonist.name}의 태도 정보 미입력. arc와 attitude 필드를 채우세요.`;
  }

  return parts.join('. ');
}

export function extractCoreRelationships(memory: WriterMemory, protagonistName?: string): string {
  const protagonist = findProtagonist(memory, protagonistName);

  if (!protagonist) {
    return '⚠️ 주인공 정보 없음.';
  }

  const rels = memory.relationships.filter(
    r => r.from === protagonist.name || r.to === protagonist.name
  );

  if (rels.length === 0) {
    return `⚠️ ${protagonist.name} 중심의 관계 정보 없음. 관계를 등록하세요.`;
  }

  return rels.map(r => {
    const other = r.from === protagonist.name ? r.to : r.from;
    return `${protagonist.name}-${other}: ${r.dynamic || r.type}`;
  }).join('\n');
}

export function extractEmotionalTheme(memory: WriterMemory): string {
  if (memory.themes.length === 0) {
    return '⚠️ 테마 정보 없음. 작품의 정서적 주제를 입력하세요.';
  }

  return memory.themes.map(t => t.description || t.name).join('. ');
}

export function extractGenreVsEmotion(memory: WriterMemory): string {
  const synopsis = memory.synopsis;
  if (synopsis?.genreVsRealEmotion) {
    return synopsis.genreVsRealEmotion;
  }

  const genre = memory.project.genre || '미지정';
  return `장르: ${genre}. 실제 정서: 미정의. genreVsRealEmotion 필드를 입력하세요.`;
}

export function extractEndingAftertaste(memory: WriterMemory): string {
  const synopsis = memory.synopsis;
  if (synopsis?.endingAftertaste) {
    return synopsis.endingAftertaste;
  }

  return '❌ 엔딩 정서 잔상 미입력. synopsis update endingAftertaste "..." 로 추가하세요.';
}

// === Synopsis State Management ===

export function saveSynopsisState(state: SynopsisState): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  memory.synopsis = { ...state, lastGenerated: now() };
  return saveMemory(memory);
}

export function loadSynopsisState(): SynopsisState | null {
  const memory = loadMemory();
  return memory?.synopsis || null;
}

export function updateSynopsisElement(element: keyof SynopsisState, value: string): boolean {
  const memory = loadMemory();
  if (!memory) return false;

  memory.synopsis = memory.synopsis || {
    protagonistAttitude: '',
    coreRelationships: '',
    emotionalTheme: '',
    genreVsRealEmotion: '',
    endingAftertaste: ''
  };

  (memory.synopsis as any)[element] = value;
  memory.synopsis.lastGenerated = now();
  return saveMemory(memory);
}

// === Format Functions ===

export function formatFullSynopsis(
  attitude: string,
  relationships: string,
  theme: string,
  genreContrast: string,
  aftertaste: string,
  memory: WriterMemory
): string {
  const projectName = memory.project.name || '제목 미정';
  const chars = Object.values(memory.characters);
  const charList = chars.map(c => `- **${c.name}**: ${c.attitude || c.arc || '설명 없음'}`).join('\n');
  const emotionFlow = memory.scenes
    .filter(s => s.emotionTags?.length > 0)
    .map(s => s.emotionTags[0])
    .join(' → ') || '아직 정의되지 않음';

  return `═══════════════════════════════
시놉시스: ${projectName}
═══════════════════════════════

## 1. 주인공의 태도
${attitude}

## 2. 관계의 핵심 구도
${relationships}

## 3. 정서적 테마
${theme}

## 4. 장르와 실제 감정의 거리
${genreContrast}

## 5. 엔딩이 남기는 잔상
${aftertaste}

---
**등장인물**:
${charList || '(등장인물 없음)'}

**장면 수**: ${memory.scenes.length}개

**감정 흐름**: ${emotionFlow}
`;
}

export function formatBriefSynopsis(
  attitude: string,
  relationships: string,
  theme: string,
  memory: WriterMemory
): string {
  const chars = Object.values(memory.characters);
  const protagonist = chars[0];
  const name = protagonist?.name || '주인공';

  return `${name}은 ${attitude.split('.')[0]}. ${theme.split('.')[0]}을 통해 ${relationships.split('\n')[0] || '관계를 형성하며'} 변화한다.`;
}

export function formatPitchSynopsis(
  attitude: string,
  relationships: string,
  theme: string,
  genreContrast: string,
  memory: WriterMemory
): string {
  const projectName = memory.project.name || '이 이야기';
  const chars = Object.values(memory.characters);
  const protagonist = chars[0];
  const name = protagonist?.name || '주인공';

  return `${projectName}는 ${attitude.split('.')[0]} ${name}이 ${theme.split('.')[0]}을 깨닫는 이야기. ${genreContrast.split('.')[0]}.`;
}

// === Checklist ===

export interface ChecklistItem {
  element: string;
  elementKr: string;
  status: 'complete' | 'partial' | 'missing';
  source: string;
  suggestion: string;
}

export function getSynopsisChecklist(memory: WriterMemory): ChecklistItem[] {
  const chars = Object.values(memory.characters);
  const protagonist = chars[0];

  const checklist: ChecklistItem[] = [];

  // 1. Protagonist Attitude
  const hasArc = protagonist?.arc ? true : false;
  const hasAttitude = protagonist?.attitude ? true : false;
  checklist.push({
    element: 'protagonistAttitude',
    elementKr: '주인공 태도 요약',
    status: hasArc && hasAttitude ? 'complete' : hasArc || hasAttitude ? 'partial' : 'missing',
    source: protagonist ? `캐릭터 '${protagonist.name}'에서 추출` : '주인공 없음',
    suggestion: hasArc && hasAttitude ? '' : 'char update <name> arc "..." attitude "..."'
  });

  // 2. Core Relationships
  const relCount = protagonist ? memory.relationships.filter(
    r => r.from === protagonist.name || r.to === protagonist.name
  ).length : 0;
  checklist.push({
    element: 'coreRelationships',
    elementKr: '관계 핵심 구도',
    status: relCount >= 2 ? 'complete' : relCount === 1 ? 'partial' : 'missing',
    source: `관계 ${relCount}개 등록됨`,
    suggestion: relCount >= 2 ? '' : 'rel add <from> <to> <type>'
  });

  // 3. Emotional Theme
  checklist.push({
    element: 'emotionalTheme',
    elementKr: '정서적 테마',
    status: memory.themes.length > 0 ? 'complete' : 'missing',
    source: `테마 ${memory.themes.length}개 등록됨`,
    suggestion: memory.themes.length > 0 ? '' : 'theme add <name>'
  });

  // 4. Genre vs Emotion
  const hasGenreContrast = memory.synopsis?.genreVsRealEmotion ? true : false;
  checklist.push({
    element: 'genreVsEmotion',
    elementKr: '장르와 실제 감정의 거리',
    status: hasGenreContrast ? 'complete' : 'missing',
    source: hasGenreContrast ? '명시적으로 입력됨' : '미입력',
    suggestion: hasGenreContrast ? '' : 'synopsis update genreVsRealEmotion "..."'
  });

  // 5. Ending Aftertaste
  const hasAftertaste = memory.synopsis?.endingAftertaste ? true : false;
  checklist.push({
    element: 'endingAftertaste',
    elementKr: '엔딩 정서 잔상',
    status: hasAftertaste ? 'complete' : 'missing',
    source: hasAftertaste ? '명시적으로 입력됨' : '미입력',
    suggestion: hasAftertaste ? '' : 'synopsis update endingAftertaste "..."'
  });

  return checklist;
}

// === Export ===

export function exportSynopsisAsMarkdown(): string {
  const memory = loadMemory();
  if (!memory) return '# Error: No memory found';

  const synopsis = generateSynopsis({ format: 'full' });
  if (!synopsis) return '# Error: Could not generate synopsis';

  const meta = `---
project: ${memory.project.name || 'Untitled'}
genre: ${memory.project.genre || 'Unspecified'}
generated: ${new Date().toISOString()}
---

`;

  return meta + synopsis;
}

export function exportSynopsisAsJSON(): object {
  const memory = loadMemory();
  if (!memory) return { error: 'No memory found' };

  const checklist = getSynopsisChecklist(memory);

  return {
    metadata: {
      project: memory.project.name,
      genre: memory.project.genre,
      generated: new Date().toISOString()
    },
    elements: {
      protagonistAttitude: extractProtagonistAttitude(memory),
      coreRelationships: extractCoreRelationships(memory),
      emotionalTheme: extractEmotionalTheme(memory),
      genreVsEmotion: extractGenreVsEmotion(memory),
      endingAftertaste: extractEndingAftertaste(memory)
    },
    checklist,
    formats: {
      full: generateSynopsis({ format: 'full' }),
      brief: generateSynopsis({ format: 'brief' }),
      pitch: generateSynopsis({ format: 'pitch' })
    }
  };
}

